return json_decode('{"published": "2026-10-22", "sources": {"www.aarp.org": {"en": "AARP"}, "time.com": {"en": "Time"}, "apnews.com": {"en": "the Associated Press"}, "www.coloradopolitics.com": {"en": "the Washington Examiner (via Colorado Politics)"}, "www.vox.com": {"en": "Vox"}, "hyperallergic.com": {"en": "Hyperallergic"}, "web.archive.org": {"en": "The Arizona Republic (archived)"}, "www.azcentral.com": {"en": "The Arizona Republic"}, "fronterasdesk.org": {"en": "KJZZ Fronteras Desk"}, "americanhistory.si.edu": {"en": "the Smithsonian\'s National Museum of American History"}, "www.newspapers.com": {"en": "The Miami Herald (Newspapers.com)"}, "en.wikipedia.org": {"en": "Wikipedia"}, "www.intab.net": {"en": "Intab"}, "www.npr.org": {"en": "NPR"}, "www.refinery29.com": {"en": "Refinery29"}, "www.law.cornell.edu": {"en": "U.S. Code (Cornell Legal Information Institute)"}, "www.justice.gov": {"en": "the U.S. Department of Justice"}, "elections.wi.gov": {"en": "the Wisconsin Elections Commission"}, "www.ilga.gov": {"en": "the Illinois Election Code"}, "www.wglt.org": {"en": "WGLT"}, "sparq.stanford.edu": {"en": "Bond et al., Nature (2012)"}, "doi.org": {"en": "the journal of record (DOI)"}, "www.povertyactionlab.org": {"en": "J-PAL"}, "fomh.org": {"en": "the Friends of Mount Hope Cemetery"}, "www.usatoday.com": {"en": "the Rochester Democrat and Chronicle (USA Today)"}, "www.smithsonianmag.com": {"en": "Smithsonian Magazine"}, "muse.jhu.edu": {"en": "the Journal of Feminist Studies in Religion"}, "electionline.org": {"en": "electionline Weekly"}, "www.marketplace.org": {"en": "Marketplace"}, "calmatters.org": {"en": "CalMatters"}, "www.metroartsnashville.gov": {"en": "Metro Arts Nashville"}, "www.eac.gov": {"en": "the U.S. Election Assistance Commission"}, "legislature.ulstercountyny.gov": {"en": "the Ulster County Legislature"}, "hudsonvalleyone.com": {"en": "Hudson Valley One"}, "spectrumlocalnews.com": {"en": "Spectrum News"}, "www2.census.gov": {"en": "the U.S. Census Bureau"}, "www.michigan.gov": {"en": "the Michigan Department of State"}, "www.thehenryford.org": {"en": "The Henry Ford museum"}, "www.bridgemi.com": {"en": "Bridge Michigan"}, "www.michiganpublic.org": {"en": "Michigan Public"}, "www.nyccfb.info": {"en": "the NYC Campaign Finance Board"}, "wnyc.org": {"en": "WNYC"}, "www.dnainfo.com": {"en": "DNAinfo"}, "sf.gov": {"en": "the San Francisco Department of Elections"}, "windnewspaper.com": {"en": "World Journal (Wind Newspaper)"}, "sos.ga.gov": {"en": "the Georgia Secretary of State"}, "www.everycrsreport.com": {"en": "the Congressional Research Service (via EveryCRSReport)"}, "recorder.pima.gov": {"en": "the Pima County Recorder"}, "app.chicagoelections.gov": {"en": "the Chicago Board of Election Commissioners"}, "chicagoelections.gov": {"en": "the Chicago Board of Election Commissioners"}, "www.clickondetroit.com": {"en": "the Associated Press (via WDIV ClickOnDetroit)"}, "www.whec.com": {"en": "News10NBC (WHEC Rochester)"}, "abc7chicago.com": {"en": "ABC7 Chicago"}, "vote.phila.gov": {"en": "the Philadelphia City Commissioners"}, "sos.oregon.gov": {"en": "the Oregon Secretary of State"}, "extcontent.stlouisco.com": {"en": "the St. Louis County Board of Elections"}, "www.wkar.org": {"en": "WKAR"}, "sentinelcolorado.com": {"en": "the Associated Press (via Sentinel Colorado)"}, "www.fvap.gov": {"en": "the Federal Voting Assistance Program"}, "portal.ct.gov": {"en": "the Connecticut Secretary of the State"}, "boe.cuyahogacounty.gov": {"en": "the Cuyahoga County Board of Elections"}, "about.fb.com": {"en": "Facebook (Meta newsroom)"}, "about.instagram.com": {"en": "Instagram"}, "research.voteamerica.org": {"en": "VoteAmerica Research Center"}, "journals.plos.org": {"en": "Jones et al., PLOS ONE (2017)"}, "hdl.handle.net": {"en": "HathiTrust Digital Library"}, "www.mentalfloss.com": {"en": "Mental Floss"}, "www.proquest.com": {"en": "The Austin Statesman (ProQuest)"}, "www.jstor.org": {"en": "JSTOR"}, "www.gutenberg.org": {"en": "Gavit, Americans by Choice (1922)"}, "archives.kdl.org": {"en": "The Lowell Ledger (Kent District Library)"}, "newspapers.swco.ttu.edu": {"en": "The Morton Tribune (Texas Tech)"}, "www.revisor.mn.gov": {"en": "Minnesota Session Laws"}, "www.wkyt.com": {"en": "WKYT"}}, "callout": {"h": {"en": "1918: The Earliest Voting Tags We Found", "es": "1918: las etiquetas para votar más antiguas que encontramos"}, "place": {"en": "Michigan", "es": "Michigan"}, "body": {"en": "On October 31, 1918, a weekly paper near Grand Rapids, Michigan, the Lowell Ledger, reported that a local Americanization society had started “a movement to tag every voter.” At the November election, it said, tags reading “I am an American. I voted. Did you?” would be handed out. A 1922 book describes the Grand Rapids campaign at the city’s March and April 1919 elections: committees of women gave voters the tags at the polls, and the only way to get one was to vote. Afterward, schoolchildren collected the tags, and the schools with the most won flags.", "es": "El 31 de octubre de 1918, un semanario cerca de Grand Rapids, Michigan, el Lowell Ledger, informó que una sociedad local de americanización había iniciado un movimiento para ponerle una etiqueta a cada votante (“a movement to tag every voter”). En la elección de noviembre, decía, se repartirían etiquetas con el texto “I am an American. I voted. Did you?” (soy estadounidense, voté, ¿y tú?). Un libro de 1922 describe la campaña de Grand Rapids en las elecciones municipales de marzo y abril de 1919: comités de mujeres les daban las etiquetas a los votantes en los lugares de votación, y la única forma de conseguir una era votar. Después, los niños juntaban las etiquetas, y las escuelas que reunían más ganaban banderas."}, "limits": {"en": "These were paper tags, pinned on, not adhesive stickers. In October 1920, a St. Louis junior high school printed “I have voted” tags for a student election. We haven’t found a record of who printed the first adhesive “I Voted” sticker. The earliest adhesive one we found is a 1950 car-window sticker reading “Thank Me I Voted Republican.”", "es": "Eran etiquetas de papel que se prendían a la ropa, no stickers adhesivos. En octubre de 1920, una escuela secundaria de St. Louis imprimió etiquetas de “I have voted” para una elección estudiantil. No hemos encontrado un registro de quién imprimió el primer sticker adhesivo de “I Voted”. El adhesivo más antiguo que encontramos es un sticker de 1950 para la ventana del carro que dice “Thank Me I Voted Republican”."}, "source": {"en": "The Lowell Ledger, Oct. 31, 1918, p. 2, on Kent District Library", "es": "The Lowell Ledger, 31 de octubre de 1918, p. 2, en Kent District Library"}, "fact": "lowell-1918-tag-notice", "facts": ["lowell-1918-tag-notice", "grandrapids-1919-tags", "thank-me-1950-sticker", "stlouis-blewett-1920"], "event": "lowell-1918", "year": 1918, "src": "https://archives.kdl.org/The%20Lowell%20Ledger/1918/10_October/10-31-1918.pdf", "quote": "Recently the Americanization society inaugurated a movement to tag every voter, which has already brought good results. The effort will be continued in the November election and tags bearing the words “I am an American. I voted. Did you?” Will be distributed.", "evidence": "newspaper", "pending": false}, "sections": [{"id": "answer", "h": {"en": "What We Know About the Sticker’s Origins", "es": "Lo que sabemos del origen del sticker"}, "paras": [{"en": "There’s no settled origin story. Paper “I have voted” tags go back at least to 1918, and the sticker most people picture took shape in the 1980s.", "facts": ["lowell-1918-tag-notice", "grandrapids-1919-tags", "stlouis-blewett-1920", "phoenix-realtors-1985", "boudreau-1987"], "es": "No hay una historia de origen definitiva. Las etiquetas de papel de “I have voted” existen por lo menos desde 1918, y el sticker que la mayoría imagina tomó forma en los años ochenta.", "src": ["https://archives.kdl.org/The%20Lowell%20Ledger/1918/10_October/10-31-1918.pdf", "https://www.gutenberg.org/files/60576/60576-h/60576-h.htm", "https://hdl.handle.net/2027/uc1.b2987052?urlappend=%3Bseq=60", "https://web.archive.org/web/20180209130609/http://archive.azcentral.com/specials/special36/articles/1108ELECT-VOTERVOICES.html", "https://www.aarp.org/events-history/i-voted-sticker-2024.html"], "pending": false}], "answer": [{"q": {"en": "The earliest examples we found", "es": "Los ejemplos más antiguos que encontramos"}, "a": {"en": "In October 1918, a Michigan paper announced plans to hand voters paper tags reading “I am an American. I voted. Did you?”, and a 1922 book describes Grand Rapids voters getting them at the polls in 1919. Later histories cite a 1950 Miami Herald item about “I Have Voted” stickers at the polls, but we haven’t read that page. The earliest adhesive “I voted” sticker we found is a 1950 party sticker for car windows.", "es": "En octubre de 1918, un periódico de Michigan anunció que se repartirían etiquetas de papel con el texto “I am an American. I voted. Did you?” (soy estadounidense, voté, ¿y tú?), y un libro de 1922 describe cómo los votantes de Grand Rapids las recibían en los lugares de votación en 1919. Historias posteriores citan una nota del Miami Herald de 1950 sobre stickers de “I Have Voted” en los lugares de votación, pero no hemos leído esa página. El sticker adhesivo de “I voted” más antiguo que encontramos es un sticker de partido de 1950 para la ventana del carro."}, "facts": ["lowell-1918-tag-notice", "grandrapids-1919-tags", "miami-herald-1950-cited", "thank-me-1950-sticker"], "src": ["https://archives.kdl.org/The%20Lowell%20Ledger/1918/10_October/10-31-1918.pdf", "https://www.gutenberg.org/files/60576/60576-h/60576-h.htm", "https://www.mentalfloss.com/history/government-politics/i-voted-sticker-history", "https://www.jstor.org/stable/community.29460360"], "pending": false}, {"q": {"en": "An early organized sticker campaign", "es": "Una de las primeras campañas organizadas"}, "a": {"en": "In 1985, the Phoenix Board of Realtors handed out “I Voted Today” stickers during a freeway bond election, hoping to lift slow afternoon turnout.", "es": "En 1985, la asociación de agentes inmobiliarios de Phoenix (Phoenix Board of Realtors) repartió stickers de “I Voted Today” (Hoy voté) durante una elección sobre bonos para autopistas, para animar la votación lenta de la tarde."}, "facts": ["phoenix-realtors-1985"], "src": ["https://web.archive.org/web/20180209130609/http://archive.azcentral.com/specials/special36/articles/1108ELECT-VOTERVOICES.html"], "pending": false}, {"q": {"en": "The familiar flag oval design", "es": "El conocido óvalo con la bandera"}, "a": {"en": "In 1987, Janet Boudreau designed a small oval with a waving flag for Intab, the election supply company she had recently bought from her father for $1.", "es": "En 1987, Janet Boudreau diseñó un pequeño óvalo con una bandera ondeando para Intab, la empresa de material electoral que acababa de comprarle a su padre por 1 dólar."}, "facts": ["boudreau-1987"], "src": ["https://www.aarp.org/events-history/i-voted-sticker-2024.html"], "pending": false}], "after": [{"h3": {"en": "What We Haven’t Verified", "es": "Lo que no hemos verificado"}, "en": "We haven’t read the 1950 Miami Herald page itself, which is in a subscription newspaper archive, so we can’t say what the stickers looked like or whether they were handed out. The tags in sources from 1918 to the 1960s were paper, and we haven’t found who first printed an adhesive “I Voted” sticker. Phoenix’s Realtors later called their sticker the first in the country, but a 1982 Miami Herald story had already described shops giving discounts to people wearing voting stickers. No patent for Boudreau’s flag oval has turned up; she has said she copyrighted the design.", "facts": ["miami-herald-1950-cited", "stlouis-blewett-1920", "phoenix-realtors-1985", "boudreau-1987", "fort-lauderdale-1982", "grandrapids-1919-tags"], "es": "No hemos leído la página del Miami Herald de 1950, que está en un archivo de periódicos por suscripción, así que no podemos decir cómo eran los stickers ni si llegaron a repartirse. Las etiquetas de las fuentes de 1918 a los años sesenta eran de papel, y no hemos encontrado quién imprimió el primer sticker adhesivo de “I Voted”. Los agentes inmobiliarios de Phoenix dijeron después que su sticker fue el primero del país, pero una nota del Miami Herald de 1982 ya describía tiendas que daban descuentos a quienes llevaban stickers de votación. No ha aparecido ninguna patente del óvalo de Boudreau; ella ha dicho que registró los derechos de autor del diseño.", "src": ["https://www.mentalfloss.com/history/government-politics/i-voted-sticker-history", "https://hdl.handle.net/2027/uc1.b2987052?urlappend=%3Bseq=60", "https://web.archive.org/web/20180209130609/http://archive.azcentral.com/specials/special36/articles/1108ELECT-VOTERVOICES.html", "https://www.aarp.org/events-history/i-voted-sticker-2024.html", "https://time.com/4541760/i-voted-sticker-history-origins/", "https://www.gutenberg.org/files/60576/60576-h/60576-h.htm"], "pending": false}]}, {"id": "timeline", "h": {"en": "I Voted Sticker Timeline", "es": "Cronología del sticker de I Voted"}, "paras": [{"en": "How a local giveaway became an Election Day tradition. Tap a date to open its story. Gaps mean we haven\'t found a documented example, not that nothing happened.", "facts": [], "es": "Cómo un pequeño obsequio local se volvió una tradición del Día de las Elecciones. Toca una fecha para abrir su historia. Los huecos significan que no hemos encontrado un ejemplo documentado, no que no pasara nada.", "src": [], "pending": false}], "timeline": true}, {"id": "makers", "h": {"en": "The People Who Designed and Spread Voting Stickers", "es": "Las personas que diseñaron y difundieron los stickers"}, "paras": [{"en": "Most voting stickers carry no designer credit. These are some of the people behind them.", "facts": [], "es": "La mayoría de los stickers para votar no dicen quién los diseñó. Estas son algunas de las personas detrás de ellos.", "src": [], "pending": false}], "cards": [{"id": "card-boudreau", "year": "1987", "place": {"en": "Intab", "es": "Intab"}, "maker": {"en": "Janet Boudreau", "es": "Janet Boudreau"}, "title": {"en": "Designing the Familiar Flag Oval", "es": "El diseño del óvalo con la bandera"}, "body": {"en": "Soon after buying Intab from her father for $1, Boudreau designed the flag oval. By 2000, she said, the company sold more than 100 million “I Voted” stickers in each election year. Her practical advice: use garment-safe adhesive, or risk damaging leather, silk and fine wool.", "es": "Poco después de comprarle Intab a su padre por 1 dólar, Boudreau diseñó el óvalo con la bandera. Para el año 2000, según dijo, la empresa vendía más de 100 millones de stickers de “I Voted” en cada año electoral. Su consejo práctico: usar pegamento que no dañe la ropa, o arriesgarte a estropear piel, seda y lana fina."}, "fact": "boudreau-1987", "src": "https://www.aarp.org/events-history/i-voted-sticker-2024.html", "quote": "Boudreau created her “I Voted” design in 1987, soon after becoming president and owner of Intab, an election supply business she purchased from her father for a single dollar.", "evidence": "creator interview", "pending": false}, {"id": "card-phoenix", "year": "1985", "place": {"en": "Phoenix, Arizona", "es": "Phoenix, Arizona"}, "maker": {"en": "Skip Rimsza and Dennis M. Burke", "es": "Skip Rimsza y Dennis M. Burke"}, "title": {"en": "Using Stickers to Lift Afternoon Turnout", "es": "Stickers para animar la votación de la tarde"}, "body": {"en": "Morning turnout was strong; afternoons lagged. During a freeway bond election, Phoenix Board of Realtors president Skip Rimsza, later the city\'s mayor, and operations director Dennis M. Burke came up with an “I Voted Today” sticker to remind late-day voters.", "es": "En la mañana se votaba mucho; en la tarde, poco. Durante una elección sobre bonos para autopistas, Skip Rimsza, presidente de la asociación de agentes inmobiliarios de Phoenix y después alcalde de la ciudad, y el director de operaciones Dennis M. Burke idearon un sticker de “I Voted Today” para recordarles a los votantes de la tarde."}, "fact": "phoenix-realtors-1985", "src": "https://web.archive.org/web/20180209130609/http://archive.azcentral.com/specials/special36/articles/1108ELECT-VOTERVOICES.html", "quote": "Rimsza and Dennis M. Burke, the board\'s operations director then, brainstormed the sticker to spark voter interest. Morning voter turnout at most elections was strong, but the afternoon was always the weakest.", "evidence": "contemporary report", "pending": false}, {"id": "card-negasi", "year": "2020", "place": {"en": "Nashville, Tennessee", "es": "Nashville, Tennessee"}, "maker": {"en": "Milka Negasi, high school senior", "es": "Milka Negasi, estudiante de último año de prepa"}, "title": {"en": "A Student’s Suffrage Centennial Design", "es": "Un diseño estudiantil por el centenario del sufragio femenino"}, "body": {"en": "Negasi\'s design marked the 100th anniversary of women\'s suffrage. When several polling places ran out during the August 2020 election, Metro Arts posted a free download.", "es": "El diseño de Negasi celebró los 100 años del voto de las mujeres. Cuando se acabó en varios lugares de votación durante la elección de agosto de 2020, Metro Arts publicó una versión gratuita para descargar."}, "fact": "nashville-runout-2020", "src": "https://www.metroartsnashville.gov/vote", "quote": "During the August 6 election, several polling locations ran out of the popular sticker, designed by Hume-Fogg Academic Magnet High School senior Milka Negasi to commemorate the Women\'s Suffrage Centennial.", "evidence": "official record", "pending": false}, {"id": "card-rowan", "year": "2022", "place": {"en": "Ulster County, New York", "es": "Ulster County, New York"}, "maker": {"en": "Hudson Rowan, age 14", "es": "Hudson Rowan, 14 años"}, "title": {"en": "Ulster County’s Online Contest Winner", "es": "El ganador en línea del concurso de Ulster County"}, "body": {"en": "Rowan designed the wild-eyed head on spidery legs for one county\'s election, not all of New York. Election commissioner Ashley Dittus opened his emailed entry first and championed it; an online vote open to anyone turned it into a national curiosity.", "es": "Rowan diseñó la cabeza de ojos desorbitados sobre patas de araña para la elección de un condado, no para todo New York. La comisionada electoral Ashley Dittus abrió primero el diseño que él envió por correo electrónico y lo apoyó; una votación en línea abierta a cualquiera lo convirtió en una curiosidad nacional."}, "fact": "ulster-rowan-2022", "src": "https://legislature.ulstercountyny.gov/news/lawmakers-to-present-hudson-rowan-with-a-pride-of-ulster-county-award-at-legislative-session-on-oct-18/", "quote": "Hudson’s unconventional design has won international acclaim and amassed over 228,200 votes worldwide.", "evidence": "official record", "pending": false}, {"id": "card-hynous", "year": "2024", "place": {"en": "Michigan", "es": "Michigan"}, "maker": {"en": "Jane Hynous, age 12", "es": "Jane Hynous, 12 años"}, "title": {"en": "Michigan’s Werewolf Meme Sticker", "es": "El sticker meme del hombre lobo de Michigan"}, "body": {"en": "Hynous\'s design, inspired by an internet meme, shows a werewolf tearing open its shirt in front of an American flag. It was one of nine winners in Michigan\'s first statewide contest and went viral on social media. A sheet of the 2024 designs is now in the collection at The Henry Ford.", "es": "El diseño de Hynous, inspirado en un meme de internet, muestra a un hombre lobo rompiéndose la camisa frente a una bandera de Estados Unidos. Fue uno de los nueve ganadores del primer concurso estatal de Michigan y se hizo viral en redes sociales. Una hoja con los diseños de 2024 ahora forma parte de la colección de The Henry Ford."}, "fact": "mi-werewolf-2024", "src": "https://www.michigan.gov/sos/resources/news/2024/09/04/secretary-benson-announces-2024-i-voted-sticker-design-contest-winners", "quote": "Elementary / Middle School Winner - Created by Jane Hynous of Grosse Pointe, a student at Brownell Middle School", "evidence": "official record", "pending": false}, {"id": "card-lavallee", "year": "2020", "place": {"en": "Alaska", "es": "Alaska"}, "maker": {"en": "Barbara Lavallee", "es": "Barbara Lavallee"}, "title": {"en": "Alaska Designs in Ten Languages", "es": "Diseños de Alaska en diez idiomas"}, "body": {"en": "Lavallee created four designs featuring Alaskan women. They came in English, Spanish, Tagalog and seven Alaska Native languages, including Koyukon, Gwich\'in and Yup\'ik, and people voting from home could download them.", "es": "Lavallee creó cuatro diseños con mujeres de Alaska. Salieron en inglés, español, tagalo y siete lenguas nativas de Alaska, entre ellas koyukon, gwich\'in y yup\'ik, y quienes votaban desde casa podían descargarlos."}, "fact": "alaska-2020-lavallee", "src": "https://www.eac.gov/clearinghouse-awards/2020-honorable-mention-creative-and-original-i-voted-stickers-alaska-72856", "quote": "The stickerswereavailable in English, Spanish, Koyukon, Gwichin, Aleut, Tagalog, Alutiiq, Northern Inupiaq, Nunivak Cupig, and Yup\'ik. For those who votedfrom home, digital stickerswereavailable for download on the Divisions website so voters could display that they exercised their right to vote.", "evidence": "official record", "pending": false}, {"id": "card-boren", "year": "2022", "place": {"en": "St. Louis County, Missouri", "es": "St. Louis County, Missouri"}, "maker": {"en": "Julia Boren, age 11", "es": "Julia Boren, 11 años"}, "title": {"en": "A Mailbox Sticker for Absentee Voters", "es": "Un sticker con buzón para quienes votan en ausencia"}, "body": {"en": "Boren\'s hand-drawn entry featured a mailbox, so the county turned it into an “I Voted at Home” sticker that goes out with absentee ballots.", "es": "El dibujo de Boren tenía un buzón, así que el condado lo convirtió en un sticker de “I Voted at Home” (Voté desde casa) que se envía con las boletas de voto en ausencia."}, "fact": "mail-stickers-stlcounty-2021", "src": "https://extcontent.stlouisco.com/BOE/biennial/2022Biennial.pdf", "quote": "As a bonus, the BOE also got a new \\"I Voted at Home\\" sticker when the artwork from eleven-year-old Julia Boren included a mailbox in the design in her hand drawn entry. The design is now included with absentee ballots mailed to St. Louis County voters.", "evidence": "official record", "pending": false}]}, {"id": "why", "h": {"en": "Why Voters Wear Them, and What Research Shows", "es": "Por qué los votantes los usan y qué dicen los estudios"}, "paras": [{"en": "Through most of the 1800s, many Americans voted with ballots printed by the political parties. The tickets were often easy to tell apart, sometimes by color, and voters handed them in where others could see. States began adopting a government-printed secret ballot in 1888, starting with Louisville and Massachusetts. As it replaced party tickets, voters could keep their choices to themselves. An “I Voted” sticker shows that a person voted without revealing how. A 1919 Grand Rapids campaign put it plainly: “Whether or not you vote is not your business; it is Uncle Sam’s business. HOW you vote is your business.”", "facts": ["secret-ballot-1888", "grandrapids-1919-tags"], "es": "Durante buena parte del siglo XIX, muchos estadounidenses votaban con boletas impresas por los partidos políticos. Era fácil distinguirlas, a veces por el color, y los votantes las entregaban a la vista de otros. Los estados empezaron a adoptar una boleta secreta impresa por el gobierno en 1888, comenzando por Louisville y Massachusetts. A medida que reemplazó a las boletas de los partidos, los votantes pudieron guardarse su elección. Un sticker de “I Voted” muestra que alguien votó sin revelar por quién. Una campaña de Grand Rapids de 1919 lo dijo claramente: votar o no es asunto del Tío Sam, y cómo votas es asunto tuyo (“Whether or not you vote is not your business; it is Uncle Sam’s business. HOW you vote is your business.”).", "src": ["https://www.everycrsreport.com/reports/IN12389.html", "https://www.gutenberg.org/files/60576/60576-h/60576-h.htm"], "pending": false}, {"en": "Researchers have tested what happens when voting becomes visible to neighbors and friends. None of the studies below tested paper “I Voted” stickers.", "es": "Hay investigaciones sobre lo que pasa cuando el voto se vuelve visible para vecinos y amigos. Ninguno de los estudios de abajo probó stickers de papel de “I Voted”.", "facts": [], "src": [], "pending": false}, {"h3": {"en": "A Michigan Mailer Study", "es": "Un estudio con cartas en Michigan"}, "en": "In a 2006 Michigan primary, researchers mailed some households a list showing whether they and their neighbors had voted. Turnout in those households was 8.1 percentage points higher than in homes that got no mailer.", "facts": ["social-pressure-2006", "ggl-neighbors-effect"], "es": "En una elección primaria de Michigan en 2006, unos investigadores enviaron por correo a algunos hogares una lista que mostraba si ellos y sus vecinos habían votado. La participación en esos hogares fue 8.1 puntos porcentuales más alta que en los que no recibieron nada.", "src": ["https://www.povertyactionlab.org/evaluation/social-pressure-and-voter-turnout-united-states", "https://www.povertyactionlab.org/evaluation/social-pressure-and-voter-turnout-united-states"], "pending": false}, {"h3": {"en": "Facebook, Election Day 2010", "es": "Facebook, Día de las Elecciones de 2010"}, "en": "On Election Day 2010, Facebook showed 61 million users a message with an “I Voted” button. Some also saw photos of friends who had already clicked it. Researchers estimated a small rise in turnout, most of it passed along through close friends rather than from the message itself. A repeat test in the 2012 presidential election found a similar small rise.", "facts": ["facebook-2010", "facebook-2012-replication"], "es": "El Día de las Elecciones de 2010, Facebook mostró a 61 millones de usuarios un mensaje con un botón de “I Voted”. Algunos también vieron fotos de amigos que ya lo habían presionado. Los investigadores estimaron un pequeño aumento en la participación, en su mayor parte transmitido por amigos cercanos y no por el mensaje mismo. Una prueba repetida en la elección presidencial de 2012 encontró un aumento pequeño parecido.", "src": ["https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/bond_et_al._2012_-_a_61-million-person_experiment_in_social_influence_political_mobilization.pdf", "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0173851"], "pending": false}, {"h3": {"en": "A Digital Sticker Test, 2018", "es": "Una prueba con un sticker digital, 2018"}, "en": "In 2018, Vote.org sent texts reminding people to vote and checked who voted afterward. Some texts also linked to a digital “I Voted” sticker to post on Facebook. Both kinds of text raised turnout by about a quarter of a percentage point (0.25 with the sticker link, 0.24 without), so the sticker added no measurable effect. The results come from the group’s own research memo, not a peer-reviewed journal.", "es": "En 2018, Vote.org mandó mensajes de texto para recordarle a la gente que votara y después revisó quién votó. Algunos mensajes también tenían un enlace a un sticker digital de “I Voted” para publicar en Facebook. Los dos tipos de mensaje subieron la participación cerca de un cuarto de punto porcentual (0.25 con el enlace al sticker, 0.24 sin él), así que el sticker no sumó un efecto medible. Los resultados vienen de un informe de investigación del propio grupo, no de una revista académica revisada por pares.", "facts": ["voteorg-2018-sticker-sms"], "src": ["https://research.voteamerica.org/2018-cold-sms-overview/"], "pending": false}], "charts": ["facebook"], "after": [{"en": "The mailer and Facebook studies tested voting made visible to neighbors or friends, and the one test of a digital sticker link found no extra effect. A paper sticker may work the same way, but these studies don’t show it.", "facts": ["facebook-2010", "social-pressure-2006", "voteorg-2018-sticker-sms"], "es": "Los estudios del correo y de Facebook probaron qué pasa cuando el voto se vuelve visible para vecinos o amigos, y la única prueba de un enlace a un sticker digital no encontró un efecto extra. Un sticker de papel puede funcionar igual, pero estos estudios no lo demuestran.", "src": ["https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/bond_et_al._2012_-_a_61-million-person_experiment_in_social_influence_political_mobilization.pdf", "https://www.povertyactionlab.org/evaluation/social-pressure-and-voter-turnout-united-states", "https://research.voteamerica.org/2018-cold-sms-overview/"], "pending": false}]}, {"id": "contests", "h": {"en": "How Communities Choose Their Voting Stickers", "es": "Cómo las comunidades eligen sus stickers"}, "paras": [{"en": "In 2019, the U.S. Election Assistance Commission created a Clearie Award category for original and creative “I Voted” stickers. Washoe County, Nevada was among the first winners, for a design with the Sierra behind the city skyline.", "facts": ["eac-clearie-sticker-2019", "washoe-2018-sierra"], "es": "En 2019, la Comisión de Asistencia Electoral de EE. UU. (U.S. Election Assistance Commission) creó una categoría de sus premios Clearie para stickers de “I Voted” originales y creativos. Washoe County, Nevada, estuvo entre los primeros ganadores, con un diseño de la Sierra detrás del perfil de la ciudad.", "src": ["https://www.eac.gov/blogs/honoring-elections-tradition-eac-2019-i-voted-sticker-clearie-awards", "https://www.eac.gov/clearinghouse-awards/2019-winner-creative-and-original-i-voted-stickers-nevada-72126"], "pending": false}, {"en": "In 2017, New Yorkers ranked the finalist designs. The winning sticker, by Marie Dagata and Scott Heinz, ran colored subway lines through the “O” in “I Voted.”", "facts": ["nyc-2017-subway"], "es": "En 2017, los neoyorquinos votaron por orden de preferencia entre los diseños finalistas. El sticker ganador, de Marie Dagata y Scott Heinz, cruzaba la “O” de “I Voted” con líneas de colores del metro.", "src": ["https://www.dnainfo.com/new-york/20170511/downtown-brooklyn/i-voted-sticker-design-winner-contest-voting"], "pending": false}, {"en": "Michigan\'s first statewide contest drew more than 480 designs and more than 57,700 public votes in 2024. In 2026 it drew 2,095 entries, and the state screened every qualifying design for AI-generated and copied artwork before the public vote.", "facts": ["mi-contest-2024", "mi-contest-2026"], "es": "El primer concurso estatal de Michigan, en 2024, recibió más de 480 diseños y más de 57,700 votos del público. En 2026 recibió 2,095 diseños, y el estado revisó cada uno que calificaba para descartar arte hecho con inteligencia artificial o copiado antes de la votación pública.", "src": ["https://www.michigan.gov/sos/resources/news/2024/09/04/secretary-benson-announces-2024-i-voted-sticker-design-contest-winners", "https://www.michigan.gov/sos/resources/news/2026/05/04/i-voted-sticker-design-contest-grows-to-over-2000-submissions"], "pending": false}, {"en": "Denver held a design contest through its program for confined voters. Two winning designs went out in the city\'s November 2024 mail-ballot packets.", "facts": ["denver-confined-2023"], "es": "Denver organizó un concurso de diseño con su programa para votantes en centros de detención. Dos diseños ganadores se enviaron en los paquetes de boletas por correo de la ciudad en noviembre de 2024.", "src": ["https://www.eac.gov/clearinghouse-awards/2023-winner-creative-and-original-i-voted-stickers-colorado-71551"], "pending": false}, {"en": "Some offices design for voters a standard sticker leaves out. Douglas County, Nevada made a braille sticker for the 2020 elections with a local artist. Palm Beach County, Florida released two in 2024 with braille and American Sign Language, one designed with Pyramid, Inc., an arts program for people with disabilities. Pima County, Arizona’s 2022 sticker added Tohono O’odham to English and Spanish.", "es": "Algunas oficinas diseñan para votantes a quienes un sticker común deja fuera. Douglas County, Nevada, hizo un sticker en braille para las elecciones de 2020 con un artista local. Palm Beach County, Florida, presentó dos en 2024 con braille y lengua de señas americana, uno diseñado con Pyramid, Inc., un programa de arte para personas con discapacidad. El sticker de 2022 de Pima County, Arizona, sumó el tohono o’odham al inglés y al español.", "facts": ["douglas-braille-2019", "palm-beach-braille-2024", "mail-stickers-pima-2022"], "src": ["https://www.eac.gov/clearinghouse-awards/2019-winner-creative-and-original-i-voted-stickers-nevada-72116", "https://eac.gov/sites/default/files/2025-04/Clearies24_FL_PalmBeach_BrailleStickers_508.pdf", "https://recorder.pima.gov/PressRelease/2022/Sticker%20Write-up%20memo%207.13.22.pdf"], "pending": false}, {"en": "Others change what a sticker can be. Colorado’s first digital sticker contest, in 2022, sent the winning design to voters through BallotTrax after they voted. In 2025, Jefferson County, Colorado gave out a scratch-and-sniff sticker after students voted on the scent.", "es": "Otras cambian lo que puede ser un sticker. El primer concurso de stickers digitales de Colorado, en 2022, les envió el diseño ganador a los votantes por BallotTrax después de votar. En 2025, Jefferson County, Colorado, repartió un sticker para raspar y oler después de que estudiantes votaran por el aroma.", "facts": ["colorado-digital-2022", "jeffco-scratch-2025"], "src": ["https://www.sos.state.co.us/pubs/newsRoom/pressReleases/2022/PR20220923Contest.html", "https://www.eac.gov/clearinghouse-awards/2025-winner-creative-and-original-i-voted-stickers-colorado-74206"], "pending": false}], "charts": ["ulster", "michigan"]}, {"id": "logistics", "h": {"en": "Who Pays for “I Voted” Stickers?", "es": "¿Quién paga los stickers de “I Voted”?"}, "paras": [{"en": "There\'s no national sticker program. State and local election offices decide whether to order them, and how many. In 2020, Kings County, California paid $2,858.41 for 60,000 stickers: one for every registered voter, or about 4.8 cents each. San Francisco\'s last order that year cost about 7 cents a sticker; generic designs bought in bulk can cost as little as a penny.", "facts": ["who-pays", "kings-county-2020-cost", "marketplace-sf-unit-cost", "marketplace-bulk-cost"], "es": "No hay un programa nacional de stickers. Las oficinas electorales estatales y locales deciden si los piden y cuántos. En 2020, Kings County, California, pagó 2,858.41 dólares por 60,000 stickers: uno por cada votante registrado, unos 4.8 centavos cada uno. El último pedido de San Francisco ese año costó unos 7 centavos por sticker; los diseños genéricos comprados al mayoreo pueden costar apenas un centavo.", "src": ["https://www.whec.com/?p=410339", "https://calmatters.org/politics/2020/10/small-county-money-election-supplies/", "https://www.marketplace.org/story/2020/11/02/are-i-voted-stickers-worth-the-cost", "https://www.marketplace.org/story/2020/11/02/are-i-voted-stickers-worth-the-cost"], "pending": false}, {"h3": {"en": "How Mail Voters Get “I Voted” Stickers", "es": "Cómo reciben el sticker quienes votan por correo"}, "en": "Some offices make sure mail voters get one too. After noticing voters dropping off mail ballots in person just to collect a sticker, San Mateo County started putting one in every mailed ballot package in 2019. Pima County, Arizona sends a trilingual sticker in English, Tohono O\'odham and Spanish. In 2012, Santa Clara County made the opposite choice and saved more than $90,000 by leaving stickers out of mail packets.", "facts": ["mail-stickers-sanmateo-2019", "mail-stickers-pima-2022", "marketplace-santaclara-2012"], "es": "Algunas oficinas se aseguran de que quienes votan por correo también reciban uno. Al notar que había votantes que entregaban en persona su boleta por correo solo para llevarse un sticker, San Mateo County empezó en 2019 a incluir uno en cada paquete de boleta por correo. Pima County, Arizona, envía un sticker trilingüe en inglés, tohono o\'odham y español. En 2012, Santa Clara County tomó la decisión contraria y ahorró más de 90,000 dólares al no incluir stickers en los paquetes por correo.", "src": ["https://www.eac.gov/sites/default/files/clearinghouseawards/2020/San_Mateo_County_Registration_and_Elections_Division_Sticker.pdf", "https://recorder.pima.gov/PressRelease/2022/Sticker%20Write-up%20memo%207.13.22.pdf", "https://www.marketplace.org/story/2020/11/02/are-i-voted-stickers-worth-the-cost"], "pending": false}, {"en": "Other offices offer digital versions. Alaska posted its 2020 designs for download, Oregon offers virtual stickers, and the Federal Voting Assistance Program offers “I Voted From” stickers for Americans voting overseas.", "facts": ["digital-stickers"], "es": "Otras oficinas ofrecen versiones digitales. Alaska publicó sus diseños de 2020 para descargar, Oregon ofrece stickers virtuales y el Programa Federal de Asistencia para Votar (Federal Voting Assistance Program) ofrece stickers de “I Voted From” para estadounidenses que votan desde el extranjero.", "src": ["https://www.eac.gov/clearinghouse-awards/2020-honorable-mention-creative-and-original-i-voted-stickers-alaska-72856"], "pending": false}, {"h3": {"en": "Sticker Shortages and Cleanup", "es": "Stickers agotados y limpieza"}, "en": "Popular designs can cause a supply problem. Ulster County had 100,000 of Hudson Rowan\'s stickers for about 90,000 expected voters in 2022 and told poll workers to give out one per person. That year the Election Assistance Commission also advised offices to order stickers at least four months ahead, because paper supplies were tight.", "facts": ["ulster-dittus-2022", "paper-2022-stickers"], "es": "Los diseños populares pueden causar falta de existencias. Ulster County tenía 100,000 stickers de Hudson Rowan para unos 90,000 votantes esperados en 2022 y pidió a los trabajadores electorales dar uno por persona. Ese mismo año, la Comisión de Asistencia Electoral recomendó pedir los stickers con al menos cuatro meses de anticipación, porque escaseaba el papel.", "src": ["https://spectrumlocalnews.com/nys/hudson-valley/politics/2022/11/02/ulster-county-viral-i-voted-sticker", "https://www.eac.gov/sites/default/files/electionofficials/SupplyChain/Paper_Supply_Chain_Risk_Management_EAC_508.pdf"], "pending": false}, {"en": "Stickers can create cleanup costs too. Chicago stopped using them for about a decade after voters stuck them on water fountains, windows and doors, leaving custodians to spend hours scraping them off. The city handed out one million wristbands in 2016, about 1.9 cents each, then returned to stickers in 2021 and 2022, partly because they fit inside mail-ballot envelopes.", "facts": ["chicago-wristbands-2016", "mail-stickers-chicago-2022"], "es": "Los stickers también generan costos de limpieza. Chicago dejó de usarlos durante una década porque los votantes los pegaban en bebederos, ventanas y puertas, y el personal de limpieza pasaba horas quitándolos. La ciudad repartió un millón de pulseras en 2016, a unos 1.9 centavos cada una, y volvió a los stickers en 2021 y 2022, en parte porque caben en los sobres de las boletas por correo.", "src": ["https://electionline.org/electionline-weekly/2016/10-13/", "https://chicagoelections.gov/sites/default/files/documents/Board-Meeting-Minutes---February-22%252C-2022.pdf"], "pending": false}]}, {"id": "law", "h": {"en": "Election Day Giveaways and Voting Laws", "es": "Regalos del Día de las Elecciones y la ley electoral"}, "paras": [{"en": "In 2008, Starbucks and Ben & Jerry\'s planned Election Day giveaways for customers wearing an “I Voted” sticker. After a reminder that election law bars rewarding people for voting, both opened the offers to everyone. Federal law makes it a crime to pay or offer something of value to get someone to vote.", "facts": ["freebies-2008", "law-18usc597"], "es": "En 2008, Starbucks y Ben & Jerry\'s planearon regalos del Día de las Elecciones para clientes con un sticker de “I Voted”. Después de un recordatorio de que la ley electoral prohíbe premiar a la gente por votar, ambas empresas abrieron sus ofertas a todos. La ley federal castiga pagar u ofrecer algo de valor para que alguien vote.", "src": ["https://www.npr.org/transcripts/96557573", "https://www.law.cornell.edu/uscode/text/18/597"], "pending": false}, {"en": "State rules can be stricter. Wisconsin election officials have said a sticker-only discount violates state law there; giveaways must be open to everyone, whether they voted or not. Check current federal and state guidance before offering an Election Day promotion. This is general information, not legal advice.", "facts": ["law-wisconsin-2020"], "es": "Las reglas estatales pueden ser más estrictas. Las autoridades electorales de Wisconsin han dicho que un descuento solo para quien muestra el sticker viola la ley estatal allí; los regalos deben ser para todos, hayan votado o no. Revisa las reglas federales y estatales vigentes antes de ofrecer una promoción del Día de las Elecciones. Esto es información general, no asesoría legal.", "src": ["https://elections.wi.gov/sites/default/files/legacy/2020-10/NR%2520Elections%2520-%2520Rules%2520about%2520Voting%2520Incentives%252010-29-20.pdf"], "pending": false}, {"en": "Illinois protects access to the sticker: if an election authority supplies them to polling places, no voter there may be denied one.", "facts": ["law-illinois-17-8"], "es": "Illinois protege el acceso al sticker: si una autoridad electoral los entrega a los lugares de votación, no se le puede negar uno a ningún votante allí.", "src": ["https://www.ilga.gov/legislation/ilcs/fulltext.asp?DocName=001000050K17-8"], "pending": false}]}, {"id": "anthony", "h": {"en": "Why Voters Leave Stickers at Susan B. Anthony\'s Grave", "es": "Por qué los votantes dejan stickers en la tumba de Susan B. Anthony"}, "paras": [{"en": "Since at least 2014, voters have left “I Voted” stickers at Susan B. Anthony\'s grave in Rochester\'s Mount Hope Cemetery, to honor her work winning women the right to vote. As many as 12,000 people visited on Election Day 2016, the first time voters could choose a woman as a major-party presidential nominee.", "facts": ["anthony-grave-stickers"], "es": "Desde al menos 2014, los votantes dejan stickers de “I Voted” en la tumba de Susan B. Anthony, en el cementerio Mount Hope de Rochester, para honrar su lucha por el derecho al voto de las mujeres. Hasta 12,000 personas la visitaron el Día de las Elecciones de 2016, la primera vez que se podía votar por una mujer como candidata presidencial de un partido grande.", "src": ["https://www.usatoday.com/story/news/politics/elections/2020/10/26/susan-b-anthonys-headstone-gets-plastic-cover-i-voted-stickers/6038655002/"], "pending": false}, {"en": "The adhesive, and the solvents used to remove it, damaged the marble. Since 2020, the cemetery\'s friends group has covered the headstone with a clear protective sleeve during election season, so visitors can leave stickers without harming the stone. A religious-studies scholar has described the practice as a kind of votive offering.", "facts": ["anthony-grave-cover-2020", "conley-2020-votive"], "es": "El pegamento, y los solventes para quitarlo, dañaron el mármol. Desde 2020, la asociación de amigos del cementerio cubre la lápida con una funda transparente durante la temporada electoral, para que los visitantes dejen sus stickers sin dañar la piedra. Una académica de estudios religiosos ha descrito esta costumbre como una especie de ofrenda votiva.", "src": ["https://www.usatoday.com/story/news/politics/elections/2020/10/26/susan-b-anthonys-headstone-gets-plastic-cover-i-voted-stickers/6038655002/", "https://muse.jhu.edu/article/764904"], "pending": false}]}, {"id": "states", "h": {"en": "Local Voting Sticker Stories by State", "es": "Historias locales de stickers por estado"}, "paras": [{"en": "Some Vote Sticker state pages include a local sticker story, from a student contest winner to a sticker written into state law. Choose a highlighted state to read one.", "facts": [], "es": "Algunas páginas estatales de Vote Sticker incluyen una historia local del sticker, desde el ganador de un concurso estudiantil hasta un sticker que aparece en la ley estatal. Elige un estado resaltado para leer una.", "src": [], "pending": false}], "map": true}, {"id": "profile", "h": {"en": "Share an “I Voted” Sticker Online", "es": "Comparte un sticker de “I Voted” en línea"}, "paras": [{"en": "Polling places still hand out paper stickers, and social apps put them online years ago.", "facts": [], "es": "Los lugares de votación siguen repartiendo stickers de papel, y las redes sociales los llevaron a internet hace años.", "src": [], "pending": false}, {"en": "Facebook’s Election Day button ran in 2008, when more than 5.4 million people used it to say they voted, and by 2014 it came in Spanish, Chinese and Korean. In 2018 Instagram added an “I Voted” sticker for Stories, with a “Yo Voté” version.", "es": "El botón del Día de las Elecciones de Facebook apareció en 2008, cuando más de 5.4 millones de personas lo usaron para decir que votaron, y para 2014 ya venía en español, chino y coreano. En 2018 Instagram agregó un sticker de “I Voted” para Stories, con una versión “Yo Voté”.", "facts": ["facebook-2008", "facebook-2014-languages", "instagram-2018"], "src": ["https://about.fb.com/news/2012/11/election-day-2012-on-facebook/", "https://about.fb.com/news/2014/11/election-day-2014-on-facebook/", "https://about.instagram.com/blog/announcements/sharing-your-election-day-excitement-on-instagram"], "pending": false}], "scenes": [{"art": "shirt", "kicker": {"en": "Physical", "es": "Físico"}, "title": {"en": "At the polls", "es": "En el lugar de votación"}, "body": {"en": "A sticker tells the people around you that you voted: at work, in line for coffee, at school pickup.", "es": "Un sticker les dice a quienes te rodean que votaste: en el trabajo, en la fila del café, a la salida de la escuela."}}, {"art": "local", "kicker": {"en": "Local", "es": "Local"}, "title": {"en": "From your community", "es": "Desde tu comunidad"}, "body": {"en": "A local artist, student or election office can make a sticker feel like it belongs where you live.", "es": "Un artista, un estudiante o una oficina electoral local puede hacer que un sticker se sienta de donde vives."}}, {"art": "profile", "kicker": {"en": "Digital", "es": "Digital"}, "title": {"en": "On your profile", "es": "En tu perfil"}, "body": {"en": "A digital sticker reaches friends you may not see that day. Use it before you vote to share a date, or afterward to say you did.", "es": "Un sticker digital llega a los amigos que tal vez no ves ese día. Úsalo antes de votar para compartir una fecha, o después para decir que ya votaste."}}], "after": [{"en": "Make a free sticker for your state and share it as your profile picture. Before you vote, add your early voting or Election Day date in the “Dates or extra text” box; afterward, pick an “I voted” design. Planning a photo at the polling place? Ballot selfie rules vary by state, so check yours first.", "facts": [], "es": "Haz un sticker gratis para tu estado y compártelo como tu foto de perfil. Antes de votar, agrega tu fecha de votación anticipada o del Día de las Elecciones en el campo de fechas o texto extra; después, elige un diseño de “I voted”. ¿Piensas tomarte una foto en el lugar de votación? Las reglas sobre selfies con la boleta cambian según el estado, así que revisa las del tuyo primero.", "src": [], "pending": false}], "cta": true}], "teasers": {"AK": {"label": {"en": "Alaska", "es": "Alaska"}, "en": "Kids\' art on the stickers, with a youth contest that picked one winner from each of five regions.", "es": "Dibujos de niños en los stickers, con un concurso juvenil que eligió un ganador de cada una de sus cinco regiones."}, "CO": {"label": {"en": "Colorado", "es": "Colorado"}, "en": "High school students compete to design the state\'s digital I Voted sticker.", "es": "Estudiantes de prepa compiten por diseñar el sticker digital de “I Voted” del estado."}, "CT": {"label": {"en": "Connecticut", "es": "Connecticut"}, "en": "State law lets poll workers hand out stickers inside the no-campaigning zone.", "es": "La ley estatal permite repartir stickers dentro de la zona donde no se puede hacer campaña."}, "FL": {"label": {"en": "Florida counties", "es": "Condados de Florida"}, "en": "In Sarasota County, a seventh grader\'s pink flamingo won a student contest.", "es": "En Sarasota County, el flamenco rosa de un estudiante de séptimo grado ganó un concurso estudiantil."}, "GA": {"label": {"en": "Georgia", "es": "Georgia"}, "en": "Five million new stickers by artist Steve Penley, sent to all 159 counties.", "es": "Cinco millones de stickers nuevos del artista Steve Penley, enviados a sus 159 condados."}, "HI": {"label": {"en": "Hawaii", "es": "Hawaii"}, "en": "A virtual sticker unlocked once your ballot was accepted for counting.", "es": "Un sticker virtual que se podía descargar cuando tu boleta era aceptada para el conteo."}, "ID": {"label": {"en": "Idaho", "es": "Idaho"}, "en": "The state\'s own voting guide ends with: grab a sticker and wear it proudly.", "es": "La guía oficial para votar del estado termina así: toma un sticker y úsalo con orgullo."}, "KS": {"label": {"en": "Kansas", "es": "Kansas"}, "en": "The state\'s what-to-expect list ends with a reminder not to forget your sticker.", "es": "La lista oficial de qué esperar al votar termina recordándote que no olvides tu sticker."}, "KY": {"label": {"en": "Kentucky", "es": "Kentucky"}, "en": "A third annual statewide contest for students from kindergarten through 12th grade.", "es": "Un tercer concurso estatal anual para estudiantes de kínder a 12.º grado."}, "LA": {"label": {"en": "Louisiana", "es": "Louisiana"}, "en": "An artist-painted sticker every election since George Rodrigue\'s Blue Dog in 2016.", "es": "Un sticker pintado por un artista en cada elección desde el Blue Dog de George Rodrigue en 2016."}, "MD": {"label": {"en": "Maryland", "es": "Maryland"}, "en": "Downloadable stickers with an oriole, a crab and the Bay Bridge, some in Spanish.", "es": "Stickers para descargar con un turpial, un cangrejo y el Bay Bridge, algunos en español."}, "MI": {"label": {"en": "Michigan", "es": "Michigan"}, "en": "A statewide contest that drew more than 2,000 designs and picked nine winners.", "es": "Un concurso estatal que recibió más de 2,000 diseños y eligió nueve ganadores."}, "MN": {"label": {"en": "Minnesota", "es": "Minnesota"}, "en": "The sticker is written into state law. It says \\"I VOTED\\" and nothing more.", "es": "El sticker está en la ley estatal. Dice “I VOTED” y nada más."}, "MO": {"label": {"en": "Lincoln County, Missouri", "es": "Lincoln County, Missouri"}, "en": "Students in grades 6 to 12 sent 151 entries for the county\'s stickers.", "es": "Estudiantes de 6.º a 12.º grado enviaron 151 diseños para los stickers del condado."}, "MS": {"label": {"en": "Mississippi", "es": "Mississippi"}, "en": "Voters designed the 2026 sticker for all 82 counties.", "es": "Los votantes diseñaron el sticker de 2026 para sus 82 condados."}, "MT": {"label": {"en": "Montana", "es": "Montana"}, "en": "A new 2026 sticker made with election officials from all 56 counties.", "es": "Un sticker nuevo para 2026, hecho con funcionarios electorales de sus 56 condados."}, "NC": {"label": {"en": "North Carolina counties", "es": "Condados de North Carolina"}, "en": "In Durham County, the public votes on finalists for the sticker.", "es": "En Durham County, el público vota por los finalistas del sticker."}, "ND": {"label": {"en": "North Dakota", "es": "North Dakota"}, "en": "\\"You Betcha I Voted\\" won the first statewide contest, picked by 4,792 voters.", "es": "“You Betcha I Voted” ganó el primer concurso estatal, elegido por 4,792 votantes."}, "NM": {"label": {"en": "Santa Fe County, New Mexico", "es": "Santa Fe County, New Mexico"}, "en": "Students design the sticker, with three winners printed this year.", "es": "Los estudiantes diseñan el sticker, con tres ganadores impresos este año."}, "NY": {"label": {"en": "Ulster County, New York", "es": "Ulster County, New York"}, "en": "Home of Hudson Rowan\'s sticker; the student contest is in its sixth year.", "es": "Hogar del sticker de Hudson Rowan; el concurso estudiantil va en su sexto año."}, "OH": {"label": {"en": "Ohio", "es": "Ohio"}, "en": "A 2019 student contest drew over 2,000 entries and 15,000 votes.", "es": "Un concurso estudiantil de 2019 recibió más de 2,000 diseños y 15,000 votos."}, "OK": {"label": {"en": "Oklahoma", "es": "Oklahoma"}, "en": "Ask for your sticker before you leave, and wear it to encourage others.", "es": "Pide tu sticker antes de salir y úsalo para animar a otros a votar."}, "OR": {"label": {"en": "Oregon", "es": "Oregon"}, "en": "Everyone votes by mail, so the stickers are virtual: \\"I Voted (The Oregon Way).\\"", "es": "Todos votan por correo, así que los stickers son virtuales: “I Voted (The Oregon Way)”."}, "RI": {"label": {"en": "Rhode Island", "es": "Rhode Island"}, "en": "The state\'s voter handbook tells you to wear your sticker after you vote.", "es": "El manual del votante del estado te dice que uses tu sticker después de votar."}, "SD": {"label": {"en": "South Dakota", "es": "South Dakota"}, "en": "Students from kindergarten to 12th grade designed the next sticker.", "es": "Estudiantes de kínder a 12.º grado diseñaron el próximo sticker."}, "TN": {"label": {"en": "Tennessee", "es": "Tennessee"}, "en": "A special America 250 edition for the country\'s 250th anniversary.", "es": "Una edición especial America 250 por el aniversario 250 del país."}, "UT": {"label": {"en": "Utah", "es": "Utah"}, "en": "In 2020 the state posted four stickers to download and print at home.", "es": "En 2020 el estado publicó cuatro stickers para descargar e imprimir en casa."}, "WV": {"label": {"en": "West Virginia", "es": "West Virginia"}, "en": "An eighth grader\'s design went to 11,000 voters in one county\'s primary.", "es": "El diseño de una estudiante de octavo grado llegó a 11,000 votantes en la primaria de un condado."}, "WY": {"label": {"en": "Wyoming", "es": "Wyoming"}, "en": "A 2019 contest marked 150 years of women\'s suffrage in the state.", "es": "Un concurso de 2019 celebró 150 años del voto de las mujeres en el estado."}}, "events": [{"id": "lowell-1918", "year": 1918, "title": {"en": "Michigan Paper Announces Plans to Tag Every Voter", "es": "Un periódico de Michigan anuncia etiquetas para cada votante"}, "body": {"en": "The Lowell Ledger, a weekly near Grand Rapids, Michigan, reports that a local Americanization society has started “a movement to tag every voter” and will hand out tags reading “I am an American. I voted. Did you?” at the November election. It’s the earliest example we found.", "es": "El Lowell Ledger, un semanario cerca de Grand Rapids, Michigan, informa que una sociedad local de americanización inició un movimiento para ponerle una etiqueta a cada votante y que repartirá etiquetas con el texto “I am an American. I voted. Did you?” (soy estadounidense, voté, ¿y tú?) en la elección de noviembre. Es el ejemplo más antiguo que encontramos."}, "fact": "lowell-1918-tag-notice", "kind": "precursor", "chip": {"en": "Michigan", "es": "Michigan"}, "mark": {"en": "Paper tags", "es": "Etiquetas"}, "src": "https://archives.kdl.org/The%20Lowell%20Ledger/1918/10_October/10-31-1918.pdf", "quote": "Recently the Americanization society inaugurated a movement to tag every voter, which has already brought good results. The effort will be continued in the November election and tags bearing the words “I am an American. I voted. Did you?” Will be distributed.", "evidence": "newspaper", "pending": false}, {"id": "grand-rapids-1919", "year": 1919, "title": {"en": "Grand Rapids Hands Out Voting Tags at the Polls", "es": "Grand Rapids reparte etiquetas en los lugares de votación"}, "body": {"en": "In Grand Rapids, Michigan, committees of women hand voters paper tags at the polls reading “I am an American. I voted. Did you?” Only voters can get one. After each election, schoolchildren collect the tags, and the schools that bring back the most win flags. The campaign was part of the city’s Americanization work, which pushed immigrants to become citizens and vote.", "es": "En Grand Rapids, Michigan, comités de mujeres les dan a los votantes etiquetas de papel en los lugares de votación que dicen “I am an American. I voted. Did you?” (soy estadounidense, voté, ¿y tú?). Solo quien vota puede recibir una. Después de cada elección, los niños juntan las etiquetas, y las escuelas que reúnen más ganan banderas. La campaña era parte del trabajo de americanización de la ciudad, que impulsaba a los inmigrantes a hacerse ciudadanos y votar."}, "fact": "grandrapids-1919-tags", "kind": "precursor", "chip": {"en": "Grand Rapids", "es": "Grand Rapids"}, "src": "https://www.gutenberg.org/files/60576/60576-h/60576-h.htm", "quote": "For the tag said: “I am an American. I voted. Did you?”", "evidence": "contemporary account", "pending": false}, {"id": "blewett-1920", "year": 1920, "order": -1, "title": {"en": "St. Louis Students Get “I Have Voted” Tags", "es": "Estudiantes de St. Louis reciben etiquetas de “I have voted”"}, "body": {"en": "For a student election at Ben Blewett Junior High School in St. Louis, the school’s printing department makes “I have voted” tags, one for each student as they vote. The school, open since 1917, already ran its own student government: each homeroom elected two delegates to a grade congress, [its first principal wrote in 1919](https://www.jstor.org/stable/1078421). A few years later, Tennessee Williams was a student there: [his 1925 Blewett yearbook](https://cdn.craft.cloud/97cd51c5-b816-4a93-aea9-fd7e2c5e47da/assets/TWAR_2005-07-Cave-HNOC_holdings.pdf) has one of his early poems.", "es": "Para una elección estudiantil en Ben Blewett Junior High School, en St. Louis, el departamento de imprenta de la escuela hace etiquetas de “I have voted” (yo voté), una para cada estudiante al votar. La escuela, abierta desde 1917, ya tenía su propio gobierno estudiantil: cada grupo elegía a dos delegados para un congreso de su grado, [según escribió su primer director en 1919](https://www.jstor.org/stable/1078421). Unos años después, Tennessee Williams estudió allí: [su anuario de Blewett de 1925](https://cdn.craft.cloud/97cd51c5-b816-4a93-aea9-fd7e2c5e47da/assets/TWAR_2005-07-Cave-HNOC_holdings.pdf) tiene uno de sus primeros poemas."}, "fact": "stlouis-blewett-1920", "kind": "precursor", "chip": {"en": "St. Louis", "es": "St. Louis"}, "src": "https://hdl.handle.net/2027/uc1.b2987052?urlappend=%3Bseq=60", "quote": "the Printing Department printed enough \\"I have voted\\" tags to give each student one as he voted; and the study hall pupils cut into strips 1400 ballot sheets.", "evidence": "official record", "pending": false}, {"id": "ribbon-1920", "year": 1920, "title": {"en": "A Woman’s First-Vote Ribbon", "es": "Un listón por el primer voto de una mujer"}, "body": {"en": "A ribbon badge in the Smithsonian marks a woman\'s first vote under the 19th Amendment. It supports the Harding and Coolidge ticket, a reminder that voting souvenirs weren\'t always nonpartisan.", "es": "Un listón del Smithsonian marca el primer voto de una mujer bajo la Enmienda 19. Apoya a la fórmula de Harding y Coolidge, un recordatorio de que los recuerdos del voto no siempre fueron no partidistas."}, "fact": "nmah-1920-first-vote-badge", "kind": "precursor", "src": "https://americanhistory.si.edu/collections/object/nmah_1051247", "quote": "Badge, Nineteenth Amendment ... ID Number 1986.0640.001 ... overall: 6 1/4 in x 2 1/4 in; 15.875 cm x 5.715 cm", "evidence": "artifact", "pending": false}, {"id": "miami-1950", "year": 1950, "title": {"en": "A Miami Herald Report of “I Have Voted” Stickers", "es": "Una nota del Miami Herald sobre stickers de “I Have Voted”"}, "body": {"en": "An October 27, 1950 Miami Herald story about a vote on a $6 million hospital expansion bond said “I Have Voted” stickers would be handed out at the polls “as a reminder to others to cast their vote,” according to [Mental Floss](https://www.mentalfloss.com/history/government-politics/i-voted-sticker-history). It’s the earliest mention of a sticker we’ve seen cited. The Herald page is in a subscription archive, and we haven’t read it ourselves.", "es": "Una nota del Miami Herald del 27 de octubre de 1950, sobre una votación de bonos de 6 millones de dólares para ampliar un hospital, decía que se repartirían stickers de “I Have Voted” en los lugares de votación “as a reminder to others to cast their vote” (como recordatorio para que otros voten), según [Mental Floss](https://www.mentalfloss.com/history/government-politics/i-voted-sticker-history). Es la mención más antigua de un sticker que hemos visto citada. La página del Herald está en un archivo por suscripción y no la hemos leído directamente."}, "fact": "miami-herald-1950-cited", "mark": {"en": "Miami", "es": "Miami"}, "kind": "uncertain", "src": "https://www.mentalfloss.com/history/government-politics/i-voted-sticker-history", "quote": "The article went on to report that “I Have Voted” stickers would be handed out at the polls “as a reminder to others to cast their vote.”", "evidence": "secondary", "pending": false}, {"id": "thank-me-1950", "year": 1950, "title": {"en": "A Car-Window “I Voted” Sticker", "es": "Un sticker de “I Voted” para la ventana del carro"}, "body": {"en": "A gummed sticker reading “Thank Me I Voted Republican,” printed with “Moisten and stick to car window,” is dated 1950 in St. Lawrence University’s Richard F. Brush Art Gallery collection. It was a party sticker for a car, not a polling-place giveaway, and it’s the earliest adhesive “I voted” sticker we found.", "es": "Un sticker engomado que dice “Thank Me I Voted Republican” (agradéceme, voté republicano), con la instrucción “Moisten and stick to car window” (humedezca y pegue en la ventana del carro), tiene fecha de 1950 en la colección de la galería Richard F. Brush de St. Lawrence University. Era un sticker de partido para el carro, no uno que se repartía en los lugares de votación, y es el sticker adhesivo de “I voted” más antiguo que encontramos."}, "fact": "thank-me-1950-sticker", "kind": "precursor", "src": "https://www.jstor.org/stable/community.29460360", "quote": "Additional text includes: Moisten and stick to car window.", "evidence": "collection record", "pending": false}, {"id": "sherman-1952", "year": 1952, "title": {"en": "Texas Voters Wear “I Have Voted, Have You?” Badges", "es": "Votantes de Texas usan insignias de “I have voted, have you?”"}, "body": {"en": "On Election Day in Sherman, Texas, “citizens who had voted put on badges: ‘I have voted, have you?’” an Associated Press report in The Austin Statesman says. It’s the earliest example we found of the “have you?” line that later stickers made familiar.", "es": "El Día de las Elecciones en Sherman, Texas, quienes ya habían votado se pusieron insignias que decían “I have voted, have you?” (ya voté, ¿y tú?), según un reporte de Associated Press en un diario de Austin (The Austin Statesman). Es el ejemplo más antiguo que encontramos de la pregunta “¿y tú?” que después se volvió común en los stickers."}, "fact": "sherman-1952-badges", "kind": "precursor", "src": "https://www.proquest.com/hnpaustinamericanstatesman/docview/1559484012", "quote": "Citizens who had voted put on badges: \\"I have voted, have you?\\"", "evidence": "newspaper", "pending": false}, {"id": "lowell-1952", "year": 1952, "title": {"en": "Lowell Scouts Hand Out “I Voted” Badges", "es": "Scouts de Lowell reparten insignias de “I Voted”"}, "body": {"en": "In Lowell, Michigan, the local paper reports that Boy Scouts will hand out “I Voted” badges at the polling place on Election Day. Grade-school pupils will collect the “I Have Voted” tags at least a block away, and the classroom that gathers the most will win an award.", "es": "En Lowell, Michigan, el periódico local informa que los Boy Scouts repartirán insignias de “I Voted” en el lugar de votación el Día de las Elecciones. Los alumnos de primaria juntarán las etiquetas de “I Have Voted” por lo menos a una cuadra de distancia, y el salón que reúna más ganará un premio."}, "fact": "lowell-1952-badges", "kind": "precursor", "src": "https://archives.kdl.org/The%20Lowell%20Ledger/1952/10_October/10-30-1952.pdf", "quote": "Mr. Rivette will also provide Boy Scouts at the polling place to pass out “I Voted” badges.", "evidence": "newspaper", "pending": false}, {"id": "morton-1960", "year": 1960, "title": {"en": "Camp Fire Members Pin Tags on Texas Voters", "es": "Integrantes de Camp Fire ponen etiquetas a votantes de Texas"}, "body": {"en": "In Morton, Texas, the Wocaha Camp Fire group helps a get-out-the-vote campaign by pinning “I Have Voted” tags on voters, the Morton Tribune reports.", "es": "En Morton, Texas, el grupo Wocaha de Camp Fire ayuda en una campaña para salir a votar poniéndoles etiquetas de “I Have Voted” a los votantes, según el Morton Tribune."}, "fact": "morton-1960-tags", "kind": "precursor", "src": "https://newspapers.swco.ttu.edu/bitstreams/955f8916-b659-424a-8739-13dff5dd4c27/download", "quote": "In another recent activity, the Wocaha’s were also helpful in the get-out-the-vote campaign, aiding in pinning “I Have Voted,” tags on voters.", "evidence": "newspaper", "pending": false}, {"id": "campfire-1962", "year": 1962, "title": {"en": "Camp Fire Handbook Suggests Election Day Tags", "es": "Un manual de Camp Fire sugiere etiquetas para el Día de las Elecciones"}, "body": {"en": "The Book of the Camp Fire Girls suggests members give out “I Have Voted” tags on Election Day.", "es": "El libro de las Camp Fire Girls sugiere que sus integrantes repartan etiquetas de “I Have Voted” el Día de las Elecciones."}, "fact": "campfire-1962-tags", "kind": "precursor", "src": "https://hdl.handle.net/2027/uc1.31175021370898?urlappend=%3Bseq=235", "quote": "Give out \\"I Have Voted\\" tags on election day.", "evidence": "official record", "pending": false}, {"id": "americus-1966", "year": 1966, "title": {"en": "Black Residents Pin Tags on Voters in Americus, Georgia", "es": "Residentes afroamericanos ponen etiquetas a votantes en Americus, Georgia"}, "body": {"en": "At an Americus, Georgia city primary, Black residents pin “I have voted” tags on voters as they leave, while every clerk and manager is white, a 1968 U.S. Commission on Civil Rights report says.", "es": "En una elección primaria municipal de Americus, Georgia, residentes afroamericanos les ponen etiquetas de “I have voted” a los votantes al salir, mientras todos los secretarios y encargados del lugar de votación son blancos, según un informe de 1968 de la Comisión de Derechos Civiles de EE. UU."}, "fact": "americus-1966-tags", "kind": "precursor", "src": "https://hdl.handle.net/2027/uiug.30112105087479?urlappend=%3Bseq=123", "quote": "When the election was held, all clerks and managers at the polling place were white, although Negroes were employed to pin \\"I have voted\\" tags on the voters as they left the polling place.", "evidence": "official record", "pending": false}, {"id": "ftl-1982", "year": 1982, "title": {"en": "Fort Lauderdale Shops Offer Sticker Discounts", "es": "Tiendas de Fort Lauderdale ofrecen descuentos por el sticker"}, "body": {"en": "A Miami Herald story reports Fort Lauderdale businesses offering discounts to customers wearing voting stickers.", "es": "Una nota del Miami Herald informa que negocios de Fort Lauderdale daban descuentos a clientes con stickers de votación."}, "fact": "fort-lauderdale-1982", "kind": "sticker", "src": "https://time.com/4541760/i-voted-sticker-history-origins/", "quote": "An Oct. 29, 1982, Miami Herald article may contain the earliest mention of such a sticker", "evidence": "secondary", "pending": false}, {"id": "bush-1984", "year": 1984, "title": {"en": "George H. W. Bush Wears “I Voted Today, Have You?”", "es": "George H. W. Bush lleva un “I Voted Today, Have You?”"}, "body": {"en": "A wire report says Vice President George H. W. Bush got one when he voted in Houston. The question turns the wearer into a reminder to others.", "es": "Un reporte de agencia dice que el vicepresidente George H. W. Bush recibió uno al votar en Houston. La pregunta (“Hoy voté, ¿y tú?”) convierte a quien lo lleva en un recordatorio para los demás."}, "fact": "bush-houston-1984", "kind": "sticker", "src": "https://www.vox.com/presidential-election/2016/11/8/13553112/i-voted-sticker", "quote": "The same year, Vice President George H. W. Bush got a sticker that said “I Voted Today — Have You?” in Houston when he cast his ballot in the presidential election in 1984, according to a report that day from the United Press International wire service.", "evidence": "secondary", "pending": false}, {"id": "phoenix-1985", "year": 1985, "title": {"en": "Phoenix Realtors Hand Out “I Voted Today” Stickers", "es": "Agentes inmobiliarios de Phoenix reparten stickers"}, "body": {"en": "During a freeway bond election, the Phoenix Board of Realtors hands out “I Voted Today” stickers, one of the earliest organized sticker campaigns documented so far.", "es": "Durante una elección sobre bonos para autopistas, la asociación de agentes inmobiliarios de Phoenix reparte stickers de “I Voted Today”, una de las primeras campañas organizadas de stickers documentadas hasta ahora."}, "fact": "phoenix-realtors-1985", "mark": {"en": "Phoenix", "es": "Phoenix"}, "kind": "sticker", "src": "https://web.archive.org/web/20180209130609/http://archive.azcentral.com/specials/special36/articles/1108ELECT-VOTERVOICES.html", "quote": "Rimsza and Dennis M. Burke, the board\'s operations director then, brainstormed the sticker to spark voter interest. Morning voter turnout at most elections was strong, but the afternoon was always the weakest.", "evidence": "contemporary report", "pending": false}, {"id": "ncs-1986", "year": 1986, "title": {"en": "National Campaign Supply Starts Selling Voting Stickers", "es": "National Campaign Supply empieza a vender stickers para votar"}, "body": {"en": "National Campaign Supply, a Florida company, says it began selling voting stickers.", "es": "National Campaign Supply, una empresa de Florida, dice que empezó a vender stickers para votar."}, "fact": "national-campaign-supply-1986", "kind": "sticker", "src": "https://time.com/4541760/i-voted-sticker-history-origins/", "quote": "National Campaign Supply claims it started selling them in 1986.", "evidence": "secondary", "pending": false}, {"id": "boudreau-1987", "year": 1987, "title": {"en": "Janet Boudreau Designs the Flag Oval", "es": "Janet Boudreau diseña el óvalo con la bandera"}, "body": {"en": "Janet Boudreau designs a white oval with a waving flag for Intab. It becomes one of the country\'s most recognizable voting sticker designs. She has said she drew it after seeing a Washington state county hand out a plain black-and-white sticker [with an X in a square](https://www.wkyt.com/2026/10/31/i-voted-sticker-creator-talks-about-how-it-started/).", "es": "Janet Boudreau diseña un óvalo blanco con una bandera ondeando para Intab. Se vuelve uno de los diseños de stickers para votar más reconocibles del país. Ella ha dicho que lo dibujó después de ver que un condado del estado de Washington repartía un sticker sencillo en blanco y negro [con una X en un cuadro](https://www.wkyt.com/2026/10/31/i-voted-sticker-creator-talks-about-how-it-started/)."}, "fact": "boudreau-1987", "mark": {"en": "Flag oval", "es": "Óvalo"}, "kind": "sticker", "src": "https://www.aarp.org/events-history/i-voted-sticker-2024.html", "quote": "Boudreau created her “I Voted” design in 1987, soon after becoming president and owner of Intab, an election supply business she purchased from her father for a single dollar.", "evidence": "creator interview", "pending": false}, {"id": "minnesota-1989", "year": 1989, "title": {"en": "Minnesota Law Says “I VOTED” and Nothing More", "es": "La ley de Minnesota: “I VOTED” y nada más"}, "body": {"en": "Minnesota’s election law lets the secretary of state send counties donated stickers that say “I VOTED” and nothing more. Election judges may offer one to each voter who has signed the polling place roster.", "es": "La ley electoral de Minnesota permite que la secretaría de estado envíe a los condados stickers donados que digan “I VOTED” y nada más. Los jueces electorales pueden ofrecerle uno a cada votante que haya firmado el registro del lugar de votación."}, "fact": "minnesota-1989-law", "kind": "sticker", "src": "https://www.revisor.mn.gov/laws/1989/0/291/", "quote": "The secretary of state may distribute stickers to the county auditors which contain the words \\"I VOTED\\" and nothing more, and which have been donated to the state without cost.", "evidence": "law", "pending": false}, {"id": "mailer-2006", "year": 2006, "title": {"en": "Michigan Study Tests Voting-History Mailers", "es": "Un estudio en Michigan prueba cartas con el historial de voto"}, "body": {"en": "A Michigan field experiment finds turnout rose when voters were told their neighbors would see whether they had voted.", "es": "Un experimento de campo en Michigan encuentra que la participación subió cuando se les dijo a los votantes que sus vecinos verían si habían votado."}, "fact": "social-pressure-2006", "kind": "research", "src": "https://www.povertyactionlab.org/evaluation/social-pressure-and-voter-turnout-united-states", "quote": "Mailing a household’s own voting record resulted in a 4.9 percentage point increase and listing neighbors’ voting records resulted in an 8.1 percentage point increase in turnout among registered voters.", "evidence": "study", "pending": false}, {"id": "freebies-2008", "year": 2008, "title": {"en": "Starbucks and Ben & Jerry\'s Open Giveaways to All", "es": "Starbucks y Ben & Jerry\'s abren sus regalos a todos"}, "body": {"en": "After a reminder about election law, Starbucks and Ben & Jerry\'s open their Election Day offers to everyone, not just customers wearing “I Voted” stickers.", "es": "Tras un recordatorio sobre la ley electoral, Starbucks y Ben & Jerry\'s abren sus ofertas del Día de las Elecciones a todos, no solo a quienes llevan stickers de “I Voted”."}, "fact": "freebies-2008", "kind": "sticker", "src": "https://www.npr.org/transcripts/96557573", "quote": "Election laws say you cannot give people free stuff to encourage them or dissuade them from voting, and a Washington state official made that point yesterday. So some other companies, Starbucks and Ben and Jerry\'s, modified their offers.", "evidence": "contemporary report", "pending": false}, {"id": "facebook-2008", "year": 2008, "order": 1, "title": {"en": "Facebook Adds an Election Day Button", "es": "Facebook agrega un botón del Día de las Elecciones"}, "body": {"en": "Facebook adds an Election Day button so people can tell friends they voted. More than 5.4 million people use it.", "es": "Facebook agrega un botón del Día de las Elecciones para que la gente les diga a sus amigos que ya votó. Más de 5.4 millones de personas lo usan."}, "fact": "facebook-2008", "mark": {"en": "Facebook", "es": "Facebook"}, "kind": "digital", "src": "https://about.fb.com/news/2012/11/election-day-2012-on-facebook/", "quote": "More than 5.4 million people indicated on Facebook that they voted on Election Day 2008 and more than 12 million people clicked the button during the 2010 midterm election.", "evidence": "official record", "pending": false}, {"id": "facebook-2010", "year": 2010, "title": {"en": "Facebook Studies Its “I Voted” Button and Turnout", "es": "Facebook estudia su botón de “I Voted” y la participación"}, "body": {"en": "Facebook shows 61 million users an Election Day message with an “I Voted” button. Researchers later measure its effect on turnout.", "es": "Facebook muestra a 61 millones de usuarios un mensaje del Día de las Elecciones con un botón de “I Voted”. Después, los investigadores miden su efecto en la participación."}, "fact": "facebook-2010", "mark": {"en": "Facebook", "es": "Facebook"}, "kind": "digital", "src": "https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/bond_et_al._2012_-_a_61-million-person_experiment_in_social_influence_political_mobilization.pdf", "quote": "Our results suggest that the Facebook social message increased turnout directly by about 60,000 voters and indirectly through social contagion by another 280,000 voters, for a total of 340,000 additional votes.", "evidence": "study", "pending": false}, {"id": "anthony-2014", "year": 2014, "title": {"en": "Voters Leave Stickers on Susan B. Anthony’s Grave", "es": "Votantes dejan stickers en la tumba de Susan B. Anthony"}, "body": {"en": "By 2014, news reports describe voters leaving “I Voted” stickers on Susan B. Anthony\'s grave in Rochester.", "es": "Para 2014, las noticias describen a votantes que dejan stickers de “I Voted” en la tumba de Susan B. Anthony en Rochester."}, "fact": "anthony-grave-stickers", "kind": "sticker", "src": "https://www.usatoday.com/story/news/politics/elections/2020/10/26/susan-b-anthonys-headstone-gets-plastic-cover-i-voted-stickers/6038655002/", "quote": "On Election Day 2016, as many as 12,000 people made the trek to Anthony’s final resting place to honor the work she did to win women the right to vote, and to mark the first time people could cast a vote for a female major-party presidential candidate, Hillary Clinton.", "evidence": "contemporary report", "pending": false}, {"id": "chicago-2016", "year": 2016, "title": {"en": "Chicago Hands Out Wristbands Instead", "es": "Chicago reparte pulseras en lugar de stickers"}, "body": {"en": "Chicago hands out a million wristbands instead of stickers, after years of custodians scraping stickers off fountains, windows and doors.", "es": "Chicago reparte un millón de pulseras en vez de stickers, después de años en que el personal de limpieza los despegaba de bebederos, ventanas y puertas."}, "fact": "chicago-wristbands-2016", "kind": "sticker", "src": "https://electionline.org/electionline-weekly/2016/10-13/", "quote": "The bands cost the city about $19,000 or 1.9 cents each for the million they ordered.", "evidence": "contemporary report", "pending": false}, {"id": "nyc-2017", "year": 2017, "title": {"en": "New York City Picks a Subway-Themed Sticker", "es": "Nueva York elige un sticker con líneas del metro"}, "body": {"en": "A public vote picks a New York City sticker with colored subway lines running through the “O” in “I Voted.”", "es": "Una votación pública elige un sticker de New York City con líneas de colores del metro que cruzan la “O” de “I Voted”."}, "fact": "nyc-2017-subway", "kind": "sticker", "src": "https://www.dnainfo.com/new-york/20170511/downtown-brooklyn/i-voted-sticker-design-winner-contest-voting", "quote": "The winning sticker features multi-colored subway lines crossing over the “O” in “I Voted.” The image, designed by Marie Dagata and Scott Heinz of Bronxville, N.Y., won out over nine other finalists in the “I Voted” sticker contest run by the NYC Campaign Finance Board, the group announced Thursday.", "evidence": "contemporary report", "pending": false}, {"id": "instagram-2018", "year": 2018, "title": {"en": "Instagram Adds an “I Voted” Sticker to Stories", "es": "Instagram agrega un sticker de “I Voted” a Stories"}, "body": {"en": "Instagram adds an “I Voted” sticker to Stories, with a “Yo Voté” version for phones set to Spanish.", "es": "Instagram agrega a Stories un sticker de “I Voted”, con una versión “Yo Voté” para los teléfonos en español."}, "fact": "instagram-2018", "mark": {"en": "Instagram", "es": "Instagram"}, "kind": "digital", "src": "https://about.instagram.com/blog/announcements/sharing-your-election-day-excitement-on-instagram", "quote": "For Election Day, we’re introducing two new ways for people in the US to share their voting excitement on Instagram: an “I Voted” sticker and a “We Voted!” story at the front of your stories bar.", "evidence": "official record", "pending": false}, {"id": "douglas-braille-2019", "year": 2019, "title": {"en": "A Braille Sticker in Douglas County, Nevada", "es": "Un sticker en braille en Douglas County, Nevada"}, "body": {"en": "Douglas County works with the Nevada Secretary of State and a local artist on a braille “I voted” sticker for the 2020 elections.", "es": "Douglas County trabaja con la Secretaría de Estado de Nevada y un artista local en un sticker de “I voted” en braille para las elecciones de 2020."}, "fact": "douglas-braille-2019", "kind": "sticker", "src": "https://www.eac.gov/clearinghouse-awards/2019-winner-creative-and-original-i-voted-stickers-nevada-72116", "quote": "In the fall of 2019, the county collaborated with the Nevadas Office of the Secretary of State and a local artist to create an accessible braille I voted sticker for use in the 2020 elections.", "evidence": "official record", "pending": false}, {"id": "eac-2019", "year": 2019, "order": 1, "title": {"en": "Federal Award Adds a Sticker Category", "es": "Un premio federal agrega una categoría de stickers"}, "body": {"en": "The U.S. Election Assistance Commission adds a Clearie Award category for original and creative “I Voted” stickers.", "es": "La Comisión de Asistencia Electoral de EE. UU. agrega a sus premios Clearie una categoría para stickers de “I Voted” originales y creativos."}, "fact": "eac-clearie-sticker-2019", "kind": "sticker", "src": "https://www.eac.gov/blogs/honoring-elections-tradition-eac-2019-i-voted-sticker-clearie-awards", "quote": "This year’s EAC Clearinghouse Awards competition will accept submissions for a special new category: original and creative “I voted” stickers.", "evidence": "official record", "pending": false}, {"id": "sanmateo-2019", "year": 2019, "order": 2, "title": {"en": "San Mateo Mails a Sticker With Every Ballot", "es": "San Mateo envía un sticker con cada boleta"}, "body": {"en": "San Mateo County begins including a sticker in every mailed ballot package.", "es": "San Mateo County empieza a incluir un sticker en cada paquete de boleta por correo."}, "fact": "mail-stickers-sanmateo-2019", "kind": "sticker", "src": "https://www.eac.gov/sites/default/files/clearinghouseawards/2020/San_Mateo_County_Registration_and_Elections_Division_Sticker.pdf", "quote": "“I Voted” stickers are so popular that many of our permanent Vote by Mail voters were dropping their ballots off at Vote Centers just to obtain their stickers.", "evidence": "official record", "pending": false}, {"id": "alaska-2020", "year": 2020, "order": 1, "title": {"en": "Alaska Offers Stickers in Ten Languages", "es": "Alaska ofrece stickers en diez idiomas"}, "body": {"en": "Barbara Lavallee\'s designs appear in ten languages, with downloadable versions for voters at home.", "es": "Los diseños de Barbara Lavallee salen en diez idiomas, con versiones para descargar para quienes votan desde casa."}, "fact": "alaska-2020-lavallee", "kind": "digital", "src": "https://www.eac.gov/clearinghouse-awards/2020-honorable-mention-creative-and-original-i-voted-stickers-alaska-72856", "quote": "The stickerswereavailable in English, Spanish, Koyukon, Gwichin, Aleut, Tagalog, Alutiiq, Northern Inupiaq, Nunivak Cupig, and Yup\'ik. For those who votedfrom home, digital stickerswereavailable for download on the Divisions website so voters could display that they exercised their right to vote.", "evidence": "official record", "pending": false}, {"id": "nashville-2020", "year": 2020, "order": 2, "title": {"en": "Nashville Runs Out of a Student’s Design", "es": "Se agota en Nashville un diseño estudiantil"}, "body": {"en": "Several polling places run out of a high school student\'s women\'s suffrage centennial sticker.", "es": "Varios lugares de votación se quedan sin el sticker de una estudiante de prepa por el centenario del voto de las mujeres."}, "fact": "nashville-runout-2020", "kind": "sticker", "src": "https://www.metroartsnashville.gov/vote", "quote": "During the August 6 election, several polling locations ran out of the popular sticker, designed by Hume-Fogg Academic Magnet High School senior Milka Negasi to commemorate the Women\'s Suffrage Centennial.", "evidence": "official record", "pending": false}, {"id": "ulster-2022", "year": 2022, "title": {"en": "Hudson Rowan Wins Ulster County’s Contest", "es": "Hudson Rowan gana el concurso de Ulster County"}, "body": {"en": "A 14-year-old\'s surreal design wins Ulster County\'s contest with more online votes than the county has residents.", "es": "El diseño surrealista de un joven de 14 años gana el concurso de Ulster County con más votos en línea que habitantes tiene el condado."}, "fact": "ulster-rowan-2022", "mark": {"en": "Ulster County", "es": "Ulster County"}, "kind": "sticker", "src": "https://legislature.ulstercountyny.gov/news/lawmakers-to-present-hudson-rowan-with-a-pride-of-ulster-county-award-at-legislative-session-on-oct-18/", "quote": "Hudson’s unconventional design has won international acclaim and amassed over 228,200 votes worldwide.", "evidence": "official record", "pending": false}, {"id": "michigan-2024", "year": 2024, "title": {"en": "Michigan Holds Its First Statewide Contest", "es": "Michigan hace su primer concurso estatal"}, "body": {"en": "Michigan\'s first statewide sticker contest selects nine winning designs, including a werewolf.", "es": "El primer concurso estatal de stickers de Michigan elige nueve diseños ganadores, entre ellos un hombre lobo."}, "fact": "mi-contest-2024", "kind": "sticker", "src": "https://www.michigan.gov/sos/resources/news/2024/09/04/secretary-benson-announces-2024-i-voted-sticker-design-contest-winners", "quote": "After the sticker design contest was launched by Secretary Benson in May, more than 480 designs were submitted and over 57,700 public votes were cast for the winners.", "evidence": "official record", "pending": false}, {"id": "jeffco-scratch-2025", "year": 2025, "title": {"en": "A Scratch-and-Sniff Sticker in Jefferson County", "es": "Un sticker para raspar y oler en Jefferson County"}, "body": {"en": "Students vote on scents for Jefferson County, Colorado’s scratch-and-sniff sticker, which a U.S. Election Assistance Commission award entry calls the nation’s first.", "es": "Estudiantes votan por los aromas del sticker para raspar y oler de Jefferson County, Colorado, que una candidatura a un premio de la Comisión de Asistencia Electoral de EE. UU. llama el primero del país."}, "fact": "jeffco-scratch-2025", "kind": "sticker", "src": "https://www.eac.gov/clearinghouse-awards/2025-winner-creative-and-original-i-voted-stickers-colorado-74206", "quote": "To revitalize interest in an odd-year election, Jefferson County tapped into voter nostalgia by launching the nations first-ever scratch-and-sniff I Voted sticker.", "evidence": "official record", "pending": false}, {"id": "michigan-2026", "year": 2026, "title": {"en": "Michigan’s Second Statewide Contest", "es": "El segundo concurso estatal de Michigan"}, "body": {"en": "Michigan\'s second statewide contest draws 2,095 entries. The state screens qualifying designs for AI-generated and copied artwork before the public vote.", "es": "El segundo concurso estatal de Michigan recibe 2,095 diseños. El estado revisa los que califican para descartar arte hecho con inteligencia artificial o copiado antes de la votación pública."}, "fact": "mi-contest-2026", "kind": "sticker", "src": "https://www.michigan.gov/sos/resources/news/2026/05/04/i-voted-sticker-design-contest-grows-to-over-2000-submissions", "quote": "The Michigan Department of State (MDOS) received 2,095 submissions to its “I Voted” sticker design contest by the May 1 deadline, four times the number of entries from the first contest in the 2024 presidential election year.", "evidence": "official record", "pending": false}], "charts": {"facebook": {"type": "split", "unit": 10000, "title": {"en": "Facebook’s Estimated Turnout Effect: Direct vs. Through Friends", "es": "Efecto estimado de Facebook: directo y a través de amigos"}, "rows": [{"label": {"en": "Direct effect", "es": "Efecto directo"}, "value": 60000, "fact": "fb-2010-direct", "approx": true, "pending": false}, {"label": {"en": "Through friends", "es": "A través de los amigos"}, "value": 280000, "fact": "fb-2010-indirect", "approx": true, "key": true, "pending": false}], "note": {"en": "Researchers estimated about 340,000 additional voters overall, most of them through friends. These are estimates, not votes Facebook counted: the study randomly assigned message versions and compared a sample of users with public voting records.", "es": "Los investigadores estimaron unos 340,000 votantes adicionales en total, la mayoría a través de sus amigos. Son estimaciones, no votos que Facebook contó: el estudio asignó al azar versiones del mensaje y comparó una muestra de usuarios con los registros públicos de votación."}, "facts": ["facebook-2010", "fb-2010-total"], "sub": {"en": "Estimated additional voters from Facebook\'s 2010 Election Day message", "es": "Votantes adicionales estimados por el mensaje de Facebook del Día de las Elecciones de 2010"}, "src": ["https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/bond_et_al._2012_-_a_61-million-person_experiment_in_social_influence_political_mobilization.pdf"], "pending": false}, "ulster": {"title": {"en": "Ulster County Contest: Online Votes vs. County Population", "es": "Concurso de Ulster County: votos en línea y población del condado"}, "rows": [{"label": {"en": "Ulster County residents (2022 estimate)", "es": "Habitantes de Ulster County (estimación de 2022)"}, "value": 182357, "fact": "ulster-population-2022", "pending": false}, {"label": {"en": "Votes for Hudson Rowan\'s design", "es": "Votos por el diseño de Hudson Rowan"}, "value": 228200, "plus": true, "fact": "ulster-rowan-votes", "key": true, "pending": false}], "note": {"en": "The online vote was open to anyone, anywhere, so a county contest drew more votes than the county has residents.", "es": "La votación en línea estaba abierta a cualquiera, desde cualquier lugar, así que un concurso de condado recibió más votos que habitantes tiene el condado."}, "facts": ["ulster-rowan-2022"], "sub": {"en": "Hudson Rowan\'s design received more than 228,200 online votes, more than Ulster County\'s roughly 182,000 residents.", "es": "El diseño de Hudson Rowan recibió más de 228,200 votos en línea, más que los cerca de 182,000 habitantes de Ulster County."}, "src": ["https://legislature.ulstercountyny.gov/news/lawmakers-to-present-hudson-rowan-with-a-pride-of-ulster-county-award-at-legislative-session-on-oct-18/", "https://www2.census.gov/programs-surveys/popest/datasets/2020-2024/counties/totals/co-est2024-alldata.csv"], "pending": false}, "michigan": {"title": {"en": "Michigan Sticker Contest Entries, 2024 and 2026", "es": "Diseños enviados al concurso de Michigan, 2024 y 2026"}, "rows": [{"label": {"en": "2024", "es": "2024"}, "value": 480, "plus": true, "fact": "mi-2024-submissions", "pending": false}, {"label": {"en": "2026", "es": "2026"}, "value": 2095, "fact": "mi-2026-submissions", "key": true, "pending": false}], "note": {"en": "Entries grew about fourfold in two years. 2024 is a minimum (\\"more than 480\\"); 2026 is the published total. The first contest also drew more than 57,700 public votes.", "es": "Los diseños enviados se multiplicaron por cuatro en dos años. 2024 es un mínimo (“más de 480”); 2026 es el total publicado. El primer concurso también recibió más de 57,700 votos del público."}, "facts": ["mi-contest-2024", "mi-contest-2026"], "sub": {"en": "Designs entered in Michigan\'s statewide sticker contest", "es": "Diseños enviados al concurso estatal de stickers de Michigan"}, "src": ["https://www.michigan.gov/sos/resources/news/2024/09/04/secretary-benson-announces-2024-i-voted-sticker-design-contest-winners", "https://www.michigan.gov/sos/resources/news/2026/05/04/i-voted-sticker-design-contest-grows-to-over-2000-submissions"], "pending": false}}, "checked": "2026-11-04", "draft": false}', true);
